      process: {"overline": "So arbeiten wir", "title": "Ein einfacher Ablauf, vom ersten Gespräch bis zur Übergabe.", "techLabel": "Für technische Teams:", "stepOne": {"title": "Ich höre zu", "text": "Sie erzählen mir, wie Ihr Unternehmen heute läuft und was Sie am meisten Zeit kostet."}, "stepTwo": {"title": "Ich zeige Ihnen eine Demo", "text": "Sie testen das System, bevor es fertig ist, und nennen die nötigen Änderungen."}, "stepThree": {"title": "Wir nehmen es in Betrieb", "text": "Ich veröffentliche das System und zeige Ihnen und Ihrem Team, wie man es nutzt."}, "stepFour": {"title": "Ich begleite Sie", "text": "Ich bleibe für Anpassungen und Verbesserungen erreichbar, wenn Ihr Unternehmen wächst."}},
