      me: {"label": "Mehr über mich", "title": "Wer hinter jedem System steht.", "lead": "Ich komme aus Bagua in Amazonas, Peru. Ich studiere Systemtechnik an der UNTRM und baue parallel echte Systeme für Unternehmen und Institutionen. Bevor ich Code schreibe, möchte ich verstehen, wie die Menschen arbeiten, die ihn nutzen werden.", "factSystems": "gebaute Systeme", "factDemos": "Demos zum Ausprobieren", "factCommits": "Code-Beiträge im letzten Jahr", "factRank": "bestes Drittel meines Studiengangs", "learningsLabel": "Was mir meine Projekte beigebracht haben", "learnOne": {"title": "Zuhören vor dem Programmieren", "text": "Beim Kommunalsystem habe ich gelernt: Ein Vorgang lässt sich nur gut digitalisieren, wenn man zuerst versteht, wie die Menschen ihn erledigen."}, "learnTwo": {"title": "Im Team arbeiten", "text": "Ich habe Systeme in Teams mit drei und vier Personen gebaut und Änderungen abgestimmt, ohne die Arbeit anderer zu stören."}, "learnThree": {"title": "Sorgfältig mit fremdem Geld umgehen", "text": "Bei der Einbindung von Online-Zahlungen habe ich gelernt, jede Abbuchung im Testmodus zu prüfen, bevor echtes Geld fließt."}, "learnFour": {"title": "Informationen schützen", "text": "In VetCare wird jede Änderung protokolliert: wer sie gemacht hat und wann. So weiß die Praxis immer, was passiert ist."}, "reportLabel": "Mein Arbeitsbericht", "reportTitle": "Beständigkeit, die man nachprüfen kann.", "reportText": "Jeder Balken ist ein Arbeitsmonat, erfasst auf GitHub, der Plattform, auf der ich den Code meiner Projekte speichere.", "reportHighlight": "Beiträge im September und Oktober 2026, meine produktivste Phase des Jahres", "reportSource": "Quelle: GitHub · Nov. 2025 – Okt. 2026 · inkl. privater Projekte", "reportLink": "Profil ansehen", "reportChartAlt": "Balkendiagramm der Code-Beiträge pro Monat, November 2025 bis Oktober 2026"},
